(async () => {
      try {
        setLoading(true);
        const url = (BASE ? `${BASE}` : "") + `/api/proteins/${id}`;
        const res = await fetch(url, { credentials: "include" });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const json: Protein = await res.json();
        setData(json);
      } catch (e: any) {
        setErr(e.message ?? "불러오기에 실패했습니다.");
      } finally {
        setLoading(false);
      }
    })

(async () => {
      try {
        setLoading(true);
        setError(null);
        const res = await api<RankingResponse>(`/api/rankings/characters?type=${type}&limit=50`);
        setData(res.items);
        setMyRank(res.myRank ?? null);
        setMyTopPercent(res.myTopPercent ?? null);
        setTotalPublic(res.totalPublic ?? 0);
      } catch (e: any) {
        setError(e?.message || "Failed to load rankings.");
      } finally {
        setLoading(false);
      }
    })
